    "paramEyebrow": "Welding Parameters",
    "paramTitle": "Socket welding: the reference values.",
    "paramLead": "Heating, changeover and cooling times for socket welding according to DVS 2207-11 (heating element 250–270 °C), the basis shown practically in the videos.",
    "paramHead": [
      "d (mm)",
      "Welding depth (mm)",
      "Heating (s)",
      "Changeover max. (s)",
      "Cooling (min)"
    ],
    "paramNote": "Reference values according to DVS 2207-11 for PP at 250–270 °C heating element temperature. The welding machine manufacturer's specifications and the processing instructions are binding; in case of doubt: watch the video, check parameters on the device.",
    "stepEyebrow": "Step-by-step procedure",
    "stepTitle": "Four procedures, one quality standard.",
    "stepLead": "Each procedure has its dimension range, and five steps that determine the connection's quality.",
    "procTabs": [
      "Socket (Manual)",
      "Socket (Machine)",
      "Electrofusion",
      "Butt Welding"
    ],
    "procs": [
      {
        "t": "Manual socket welding, up to d63",
        "steps": [
          {
            "t": "Cut & deburr",
            "d": "Cut pipe at right angles, cleanly deburr and chamfer, use pipe cutter from the K Aqua tool range."
          },
          {
            "t": "Mark welding depth",
            "d": "Mark insertion depth on the pipe according to the table (e.g. 14 mm for d20), it defines the joining zone."
          },
          {
            "t": "Simultaneous heating",
            "d": "Push pipe into the heating bush, fitting onto the heating spigot, slide on simultaneously and keep the heating time exactly."
          },
          {
            "t": "Join swiftly, without twisting",
            "d": "Join axially within the changeover time. Never twist: twisting destroys the plasticized structure."
          },
          {
            "t": "Fix & cool",
            "d": "Fix connection for a few seconds, then wait the cooling time before mechanical load is applied."
          }
        ]
      },
      {
        "t": "Machine socket welding, medium dimensions",
        "steps": [
          {
            "t": "Prepare as with manual welding",
            "d": "Cut to length, deburr, mark welding depth, the basic rules remain identical."
          },
          {
            "t": "Clamp pipe & fitting",
            "d": "The machine holds both joining partners coaxially, offset and tilt errors are mechanically excluded."
          },
          {
            "t": "Heat with heating element",
            "d": "Heating bush and spigot according to DVS reference values; the machine maintains position and time reproducibly."
          },
          {
            "t": "Machine joining",
            "d": "The feed joins axially and evenly, the key to constant quality, especially for d75 to d125."
          },
          {
            "t": "Cool under fixation",
            "d": "Only unclamp and process further after the cooling time has elapsed."
          }
        ]
      },
      {
        "t": "Electrofusion, heating coil fittings",
        "steps": [
          {
            "t": "Peel surface",
            "d": "Peel and clean the pipe surface in the joining zone, oxide skin and dirt prevent welding."
          },
          {
            "t": "Mark insertion depth",
            "d": "Mark depth on the pipe, push pipe into the fitting up to the stop."
          },
          {
            "t": "Fix tension-free",
            "d": "Use holding clamps, the fitting must not be under bending stress during welding."
          },
          {
            "t": "Start welding process",
            "d": "The device energizes the embedded heating coils in the fitting, parameters come from the fitting, not from feeling."
          },
          {
            "t": "Observe cooling time",
            "d": "Only move or load after the specified cooling time, check control indicators on the fitting."
          }
        ]
      },
      {
        "t": "Butt Fusion, large dimensions up to d630",
        "steps": [
          {
            "t": "Face ends",
            "d": "Face both pipe ends in the machine until continuous shavings appear, plane parallelism is mandatory."
          },
          {
            "t": "Align & check offset",
            "d": "Maximum offset 10% of the wall thickness, every millimeter counts at d630."
          },
          {
            "t": "Heat on the heating element",
            "d": "Equalize under pressure until a bead forms, then heat through without pressure, times according to DVS 2207-11."
          },
          {
            "t": "Change over & join",
            "d": "Remove the heating element swiftly and bring the ends together under defined joining pressure."
          },
          {
            "t": "Cool under joining pressure",
            "d": "The joining pressure remains until the end of the cooling time, then the homogeneous, permanently tight string is created."
          }
        ]
      }
    ],
    "errEyebrow": "Defectology",
    "errTitle": "The six most expensive mistakes, and their prevention.",
    "errHead": [
      "Mistake",
      "Consequence",
      "Prevention"
